extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var audio = instantiate_script("res://assets/audio/audio.gd")
	if not check("instantiate", audio != null, "Lo script res://assets/audio/audio.gd deve potersi istanziare"):
		return

	if not check("play_music_func", has_function(audio, "play_music"), "AudioManager deve contenere la funzione play_music"):
		return
	if not check("stop_music_func", has_function(audio, "stop_music"), "AudioManager deve contenere la funzione stop_music"):
		return
	if not check("play_sfx_func", has_function(audio, "play_sfx"), "AudioManager deve contenere la funzione play_sfx"):
		return
	if not check("get_active_func", has_function(audio, "get_active_music_player"), "AudioManager deve contenere la funzione get_active_music_player"):
		return

	var music: AudioStream = load("res://assets/audio/music_loop.wav") as AudioStream
	if not check("music_file", music != null, "La risorsa res://assets/audio/music_loop.wav deve esistere"):
		return

	call_if_exists(audio, "play_music", [music, 0.2])
	var active = call_if_exists(audio, "get_active_music_player")
	if not check("active_player", active != null, "Dopo play_music() deve esserci un riproduttore attivo"):
		return

	var is_playing: bool = bool(get_prop(active, "playing", false))
	check("music_playing", is_playing, "Il riproduttore musicale attivo deve aver avviato la riproduzione")

	await wait_seconds(0.08)
	var vol_mid: float = float(get_prop(active, "volume_db", -80.0))
	check("fade_in_progress", vol_mid > -75.0, "Durante la dissolvenza il volume deve salire (misurato: %.1f dB)" % vol_mid)

	await wait_seconds(0.2)
	var vol_end: float = float(get_prop(active, "volume_db", -80.0))
	check("fade_reached", vol_end >= -2.0, "Al termine della dissolvenza il volume deve raggiungere circa 0.0 dB (misurato: %.1f dB)" % vol_end)

	var sfx: AudioStream = load("res://assets/audio/coin.wav") as AudioStream
	var child_count_before: int = (audio as Node).get_child_count()
	call_if_exists(audio, "play_sfx", [sfx])
	var child_count_after: int = (audio as Node).get_child_count()
	check("sfx_spawned", child_count_after > child_count_before, "La funzione play_sfx() deve creare un nuovo nodo AudioStreamPlayer per l'effetto")

	call_if_exists(audio, "stop_music", [0.15])
	await wait_seconds(0.2)
	var active_after = call_if_exists(audio, "get_active_music_player")
	var is_still_playing: bool = bool(get_prop(active_after, "playing", false)) if active_after != null else false
	check("music_stopped", not is_still_playing, "Dopo stop_music() la musica deve essersi fermata")

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var audio = instantiate_script("res://assets/audio/audio.gd")
	if not check("instantiate", audio != null, "Lo script res://assets/audio/audio.gd deve potersi istanziare"):
		return

	if not check("play_voice_func", has_function(audio, "play_voice"), "AudioManager deve avere il metodo play_voice"):
		return
	if not check("stop_voice_func", has_function(audio, "stop_voice"), "AudioManager deve avere il metodo stop_voice"):
		return
	if not check("get_voice_func", has_function(audio, "get_voice_player"), "AudioManager deve avere il metodo get_voice_player"):
		return

	var voice_player = call_if_exists(audio, "get_voice_player")
	if not check("voice_player_exists", voice_player is AudioStreamPlayer, "get_voice_player() deve restituire un nodo AudioStreamPlayer"):
		return

	var voice_1: AudioStream = load("res://assets/audio/coin.wav") as AudioStream
	var voice_2: AudioStream = load("res://assets/audio/jump.wav") as AudioStream

	call_if_exists(audio, "play_voice", [voice_1])
	var playing_1: bool = bool(get_prop(voice_player, "playing", false))
	var stream_1 = get_prop(voice_player, "stream")
	check("voice_1_playing", playing_1 and stream_1 == voice_1, "play_voice() deve avviare la riproduzione del file vocale")

	call_if_exists(audio, "play_voice", [voice_2])
	var playing_2: bool = bool(get_prop(voice_player, "playing", false))
	var stream_2 = get_prop(voice_player, "stream")
	check("voice_2_replaces", playing_2 and stream_2 == voice_2, "Una nuova voce deve sostituire immediatamente quella precedente sullo stesso canale")

	call_if_exists(audio, "stop_voice")
	var playing_after: bool = bool(get_prop(voice_player, "playing", false))
	check("voice_stopped", not playing_after, "stop_voice() deve fermare la riproduzione della voce")

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var screen: Node = await instantiate_scene("res://story/story_screen.tscn")
	if not check("screen_loaded", screen != null, "La scena res://story/story_screen.tscn deve potersi istanziare"):
		return

	var interpreter: Node = find_by_name(screen, "StoryInterpreter")
	if not check("interpreter_found", interpreter != null, "Nella scena deve essere presente il nodo StoryInterpreter"):
		return

	var audio_manager: Node = find_by_name(screen, "AudioManager")
	if not check("audio_manager_found", audio_manager != null, "Nella scena deve essere presente il nodo AudioManager"):
		return

	var assigned_audio = get_prop(interpreter, "audio_manager")
	check("audio_manager_assigned", assigned_audio == audio_manager, "La proprietà audio_manager di StoryInterpreter deve fare riferimento al nodo AudioManager")

	if not check("execute_cmd_exists", has_function(interpreter, "execute_command"), "StoryInterpreter deve avere il metodo execute_command"):
		return

	await call_if_exists(interpreter, "execute_command", [{
		"type": "music",
		"path": "res://assets/audio/music_loop.wav",
		"fade": 0.2
	}])

	var active_music = call_if_exists(audio_manager, "get_active_music_player")
	if not check("music_started", active_music != null and bool(get_prop(active_music, "playing", false)), "Il comando 'music' deve avviare la riproduzione della musica"):
		return

	await wait_seconds(0.08)
	var mid_vol: float = float(get_prop(active_music, "volume_db", -80.0))
	check("fade_in_cmd", mid_vol > -75.0, "La dissolvenza del comando 'music' deve incrementare gradualmente il volume (misurato: %.1f dB)" % mid_vol)

	await wait_seconds(0.2)
	var end_vol: float = float(get_prop(active_music, "volume_db", -80.0))
	check("fade_finished_cmd", end_vol >= -2.0, "Al termine della dissolvenza il volume della musica deve essere circa 0.0 dB (misurato: %.1f dB)" % end_vol)

	var child_count_before: int = audio_manager.get_child_count()
	await call_if_exists(interpreter, "execute_command", [{
		"type": "sfx",
		"path": "res://assets/audio/coin.wav"
	}])
	var child_count_after: int = audio_manager.get_child_count()
	check("sfx_cmd", child_count_after > child_count_before, "Il comando 'sfx' deve creare un riproduttore autonomo per l'effetto")

	await call_if_exists(interpreter, "execute_command", [{
		"type": "voice",
		"path": "res://assets/audio/jump.wav"
	}])
	var voice_player = call_if_exists(audio_manager, "get_voice_player")
	var voice_playing: bool = bool(get_prop(voice_player, "playing", false)) if voice_player != null else false
	check("voice_cmd", voice_playing, "Il comando 'voice' deve avviare la traccia vocale sul canale dedicato")

	await call_if_exists(interpreter, "execute_command", [{
		"type": "stop_music",
		"fade": 0.15
	}])
	await wait_seconds(0.2)
	var active_after = call_if_exists(audio_manager, "get_active_music_player")
	var still_playing: bool = bool(get_prop(active_after, "playing", false)) if active_after != null else false
	check("stop_music_cmd", not still_playing, "Il comando 'stop_music' deve fermare la musica al termine della dissolvenza")

